#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
struct Dinic {
    struct Edge { int to, cap, rev; };
    vector<vector<Edge>> g;
    vector<int> level, ptr;
    int src, sink;
    Dinic(int n, int s, int t) : g(n), level(n), ptr(n), src(s), sink(t) {}
    void addEdge(int u, int v, int f) {
        int revU = (int)g[u].size();
        int revV = (int)g[v].size();
        g[u].push_back({v, f, revV});
        g[v].push_back({u, 0, revU});
    }
    bool bfs() {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        q.push(src);
        level[src] = 0;
        while (!q.empty()) {
            int cur = q.front(); q.pop();
            for (int i = 0; i < (int)g[cur].size(); ++i) {
                Edge &e = g[cur][i];
                if (level[e.to] == -1 && e.cap != 0) {
                    level[e.to] = level[cur] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[sink] != -1;
    }
    int dfs(int cur, int pushed) {
        if (cur == sink) return pushed;
        for (int &i = ptr[cur]; i < (int)g[cur].size(); ++i) {
            Edge &e = g[cur][i];
            if (level[e.to] == level[cur] + 1 && e.cap != 0) {
                int tr = dfs(e.to, min(pushed, e.cap));
                if (tr) {
                    e.cap -= tr;
                    g[e.to][e.rev].cap += tr;
                    return tr;
                }
            }
        }
        return 0;
    }
    ll maxFlow() {
        ll flow = 0;
        while (bfs()) {
            fill(ptr.begin(), ptr.end(), 0);
            while (true) {
                int pushed = dfs(src, 2e9);
                if (!pushed) break;
                flow += pushed;
            }
        }
        return flow;
    }
};
int n, tLimit;
string grid[15], exits[15];
int dist[15][15];
int sy, sx;
const int dy[4] = {1, -1, 0, 0};
const int dx[4] = {0, 0, 1, -1};
void solve() {
    queue<pair<int,int>> q;
    q.push({sy,sx});
    dist[sy][sx] = 1;
    int depth = 1;
    while (!q.empty()) {
        int sz = (int)q.size();
        for (int it = 0; it < sz; ++it) {
            auto p = q.front(); q.pop();
            for (int d = 0; d < 4; ++d) {
                int ny = p.first + dy[d];
                int nx = p.second + dx[d];
                if (ny < 0 || ny >= n || nx < 0 || nx >= n) continue;
                if (dist[ny][nx] || grid[ny][nx] == 'Y') continue;
                dist[ny][nx] = depth;
                q.push({ny,nx});
            }
        }
        ++depth;
        depth = min(depth, tLimit);
    }
}
int nodeId[15][15][65];
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> tLimit;
    for (int i = 0; i < n; ++i) {
        cin >> grid[i];
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 'Z') { sy = i; sx = j; }
        }
    }
    getline(cin, grid[n]);
    getline(cin, grid[n]);
    for (int i = 0; i < n; ++i) cin >> exits[i];
    solve();
    int nodes = 0;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] >= '0' && grid[i][j] <= '9') {
                if (dist[i][j] == 0) dist[i][j] = tLimit;
                for (int t = 0; t < dist[i][j]; ++t) nodeId[i][j][t] = ++nodes;
            }
            if (exits[i][j] >= '1' && exits[i][j] <= '9') nodeId[i][j][dist[i][j]] = ++nodes;
        }
    int INF = (int)1e9;
    int S = 0, T = nodes + 3;
    Dinic mf(nodes + 5, S, T);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] >= '1' && grid[i][j] <= '9')
                mf.addEdge(S, nodeId[i][j][0], grid[i][j] - '0');
            for (int d = 0; d < 4; ++d) {
                int ny = i + dy[d], nx = j + dx[d];
                if (ny < 0 || ny >= n || nx < 0 || nx >= n) continue;
                if (grid[ny][nx] == 'Y' || grid[ny][nx] == 'Z') continue;
                for (int t = 0;; ++t) {
                    if (nodeId[i][j][t] == 0) break;
                    if (t == dist[i][j] && exits[i][j] >= '1' && exits[i][j] <= '9') break;
                    if (nodeId[ny][nx][t+1])
                        mf.addEdge(nodeId[i][j][t], nodeId[ny][nx][t+1], INF);
                }
            }
            if (exits[i][j] >= '1' && exits[i][j] <= '9') {
                for (int t = 0; t < dist[i][j]; ++t)
                    mf.addEdge(nodeId[i][j][t], nodeId[i][j][t+1], INF);
                mf.addEdge(nodeId[i][j][dist[i][j]], T, exits[i][j] - '0');
            }
        }
    }
    cout << mf.maxFlow() << '\n';
}
